*/


CheckArrVar = new Array();
CheckArrVarAlt = new Array();
CheckArrVar[0] = "fbzNetcap";
CheckArrVarAlt[0] = "영업용순자본금";
CheckArrVar[1] = "totRiskAmt";
CheckArrVarAlt[1] = "총위험금액";
CheckArrVar[2] = "eqtycap";
CheckArrVarAlt[2] = "자기자본금";
CheckArrVar[3] = "otcDrvfncTrdTotRiskAmt";
CheckArrVarAlt[3] = "장외파생금융상품거래총위험금액";
CheckArrVar[4] = "reqPersisPrincCapVal";
CheckArrVarAlt[4] = "필요유지 자기자본";
/**
 * @method
 * @name fn_CommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CommaValueAll = function() {
    fn_ObjValueSetComma(form["fbzNetcap"]); // 영업용순자본금                                    
    fn_ObjValueSetComma(form["totRiskAmt"]); // 총위험금액                            

    fn_ObjValueSetComma(form["eqtycap"]); // 자기자본금                                        
    fn_ObjValueSetComma(form["otcDrvfncTrdTotRiskAmt"]); // 장외파생금융상품거래총위험금액   

    fn_ObjValueSetComma(form["reqPersisPrincCapVal"]); // 필요유지 자기자본  

};
/**
 * @method
 * @name fn_RmCommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RmCommaValueAll = function() {
    fn_ObjValueResetRmComma(form["fbzNetcap"]); // 영업용순자본금                                    
    fn_ObjValueResetRmComma(form["totRiskAmt"]); // 총위험금액                   

    fn_ObjValueResetRmComma(form["eqtycap"]); // 자기자본금                                        
    fn_ObjValueResetRmComma(form["otcDrvfncTrdTotRiskAmt"]); // 장외파생금융상품거래총위험금액 

    fn_ObjValueResetRmComma(form["reqPersisPrincCapVal"]); // 필요유지 자기자본 

};
